pm.test("All posts have non-empty 'title' and 'body'", function () {
    const posts = pm.response.json();

    posts.forEach((post, index) => {
        const identifier = post.id ? `Post ID ${post.id}` : `Index ${index}`;

        // Ensure fields exist, are strings, and contain non-whitespace characters
        pm.expect(post.title, `${identifier} title should be a string`).to.be.a("string");
        pm.expect(post.title.trim(), `${identifier} title should not be empty`).to.not.be.empty;

        pm.expect(post.body, `${identifier} body should be a string`).to.be.a("string");
        pm.expect(post.body.trim(), `${identifier} body should not be empty`).to.not.be.empty;
    });
});

// and none of the fields contain the word zombie;
pm.test("None of the fields contain the word 'zombie'", function () {
    const posts = pm.response.json();
    const restrictedWordPattern = /\bzombie\b/i;

    posts.forEach((post, index) => {
        const identifier = post.id ? `Post ID ${post.id}` : `Index ${index}`;

        // Dynamically validate all key-value pairs across the entity
        Object.entries(post).forEach(([key, value]) => {
            pm.expect(
                restrictedWordPattern.test(String(value)),
                `${identifier} -> field '${key}' contains restricted word 'zombie'`
            ).to.be.false;
        });
    });
});

